-- M3: property billing, disabled by default. No existing booking/payment rows modified.
begin;
set local lock_timeout='5s';set local statement_timeout='90s';
alter table public.places_plan_settings add column billing_enabled boolean not null default false;
create table public.places_premium_plans(
 id uuid primary key default gen_random_uuid(),code text not null unique,name text not null check(length(btrim(name)) between 2 and 100),price_idr bigint not null check(price_idr between 1 and 999999999999),duration_months integer not null check(duration_months in(1,12)),features text[] not null default '{}',promo_price_idr bigint check(promo_price_idr between 1 and price_idr),promo_until timestamptz,available boolean not null default false,effective_at timestamptz not null default now(),version integer not null default 1 check(version>0),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id) on delete restrict,check(promo_price_idr is null or promo_until is not null),check(cardinality(features)<=30));
insert into public.places_premium_plans(code,name,price_idr,duration_months,features)
 select 'monthly','Places Premium Bulanan',greatest(premium_monthly_price_idr,1),1,array['Website properti','Digital Property Kit','Inquiry WhatsApp tanpa komisi'] from public.places_plan_settings where id
 union all select 'yearly','Places Premium Tahunan',greatest(premium_yearly_price_idr,1),12,array['Website properti','Digital Property Kit','Inquiry WhatsApp tanpa komisi'] from public.places_plan_settings where id;
create table public.places_trial_eligibility(property_id uuid primary key references public.places_properties(id) on delete restrict,eligible boolean not null default false,updated_by uuid not null references auth.users(id) on delete restrict,updated_at timestamptz not null default now());
create table public.places_billing_invoices(
 id uuid primary key default gen_random_uuid(),code text not null unique default 'SHP-P-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),property_id uuid not null references public.places_properties(id) on delete restrict,payer_id uuid not null references auth.users(id) on delete restrict,request_id uuid not null,plan_id uuid not null references public.places_premium_plans(id) on delete restrict,plan_version integer not null,plan_snapshot jsonb not null,amount_idr bigint not null check(amount_idr between 1 and 999999999999),duration_months integer not null check(duration_months in(1,12)),bank_snapshot jsonb not null,
 revenue_category text not null default 'PLACES_PREMIUM_SUBSCRIPTION' check(revenue_category='PLACES_PREMIUM_SUBSCRIPTION'),status text not null default 'OPEN' check(status in('OPEN','SETTLED','CANCELLED','EXPIRED')),payment_status text not null default 'UNPAID' check(payment_status in('UNPAID','PENDING_VERIFICATION','REQUIRES_ACTION','PAID','PARTIALLY_REFUNDED','REFUNDED')),deadline_at timestamptz not null default now()+interval '1 day',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),settled_at timestamptz,subscription_id uuid unique references public.places_subscriptions(id) on delete restrict,unique(payer_id,request_id),check(deadline_at>created_at),check((status='SETTLED')=(payment_status in('PAID','PARTIALLY_REFUNDED','REFUNDED'))),check(status<>'SETTLED' or subscription_id is not null and settled_at is not null));
create unique index places_one_open_invoice on public.places_billing_invoices(property_id) where status='OPEN';
create index places_invoices_payer_date_idx on public.places_billing_invoices(payer_id,created_at desc);create index places_invoices_property_idx on public.places_billing_invoices(property_id,created_at desc);create index places_invoices_review_idx on public.places_billing_invoices(payment_status,deadline_at);
create table public.places_billing_proofs(id uuid primary key,invoice_id uuid not null references public.places_billing_invoices(id) on delete restrict,submitted_by uuid not null references auth.users(id) on delete restrict,object_path text not null unique,source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),byte_size integer not null check(byte_size between 1 and 5242880),content_type text not null check(content_type='image/webp'),status text not null default 'PENDING' check(status in('PENDING','APPROVED','REJECTED')),review_note text not null default '',created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references auth.users(id) on delete restrict);
create unique index places_one_pending_proof on public.places_billing_proofs(invoice_id) where status='PENDING';create index places_proofs_invoice_idx on public.places_billing_proofs(invoice_id,created_at desc);
-- Immutable platform cash ledger, independent from accommodation booking gross/margin.
create table public.places_platform_cash_entries(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.places_billing_invoices(id) on delete restrict,request_id uuid not null unique,entry_type text not null check(entry_type in('RECEIPT','REFUND')),amount_idr bigint not null check(amount_idr between 1 and 999999999999),bank_reference text not null unique check(length(btrim(bank_reference)) between 6 and 200),note text not null check(length(btrim(note)) between 10 and 2000),verified_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),revenue_category text not null default 'PLACES_PREMIUM_SUBSCRIPTION' check(revenue_category='PLACES_PREMIUM_SUBSCRIPTION'));
create unique index places_single_receipt on public.places_platform_cash_entries(invoice_id) where entry_type='RECEIPT';create index places_cash_invoice_idx on public.places_platform_cash_entries(invoice_id,created_at desc);create index places_cash_date_idx on public.places_platform_cash_entries(created_at);
alter table public.places_premium_plans enable row level security;alter table public.places_trial_eligibility enable row level security;alter table public.places_billing_invoices enable row level security;alter table public.places_billing_proofs enable row level security;alter table public.places_platform_cash_entries enable row level security;
revoke all on public.places_premium_plans,public.places_trial_eligibility,public.places_billing_invoices,public.places_billing_proofs,public.places_platform_cash_entries from public,anon,authenticated;
grant select(id,code,name,price_idr,duration_months,features,promo_price_idr,promo_until,available,effective_at,version,updated_at) on public.places_premium_plans to anon,authenticated;grant select on public.places_trial_eligibility,public.places_billing_invoices,public.places_billing_proofs,public.places_platform_cash_entries to authenticated;grant all on public.places_premium_plans,public.places_trial_eligibility,public.places_billing_invoices,public.places_billing_proofs,public.places_platform_cash_entries to service_role;
create policy places_plan_read on public.places_premium_plans for select to anon,authenticated using(public.is_shiap_admin() or available and effective_at<=now());
create policy places_trial_member_read on public.places_trial_eligibility for select to authenticated using(public.is_shiap_admin() or shiap_private.places_member(property_id,false));
create function shiap_private.places_billing_owner(p_property_id uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.places_property_members where property_id=p_property_id and user_id=auth.uid() and role='OWNER' and status='ACTIVE' and verified_at is not null)$$;
revoke all on function shiap_private.places_billing_owner(uuid) from public,anon;grant execute on function shiap_private.places_billing_owner(uuid) to authenticated,service_role;
create policy places_invoice_owner_read on public.places_billing_invoices for select to authenticated using(public.is_shiap_admin() or payer_id=auth.uid() and shiap_private.places_billing_owner(property_id));
create policy places_proof_owner_read on public.places_billing_proofs for select to authenticated using(public.is_shiap_admin() or exists(select 1 from public.places_billing_invoices i where i.id=invoice_id and i.payer_id=auth.uid() and shiap_private.places_billing_owner(i.property_id)));
create policy places_cash_admin_read on public.places_platform_cash_entries for select to authenticated using(public.is_shiap_admin());
create function shiap_private.places_immutable_cash() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Cash history is immutable; record an authorized adjustment.' using errcode='42501';end$$;
revoke all on function shiap_private.places_immutable_cash() from public,anon,authenticated;
create trigger places_cash_immutable before update or delete on public.places_platform_cash_entries for each row execute function shiap_private.places_immutable_cash();
alter table public.places_subscriptions drop constraint places_subscriptions_status_check,drop constraint places_subscriptions_check1,drop constraint places_subscriptions_check3;
alter table public.places_subscriptions add constraint places_subscriptions_status_check check(status in('TRIALING','PENDING_PAYMENT','PENDING_VERIFICATION','ACTIVE','SCHEDULED','EXPIRED','CANCELLED','SUSPENDED')),add constraint places_subscription_period_required check(status not in('TRIALING','ACTIVE','SCHEDULED') or starts_at is not null and ends_at is not null),add constraint places_subscription_payment_verified check(status not in('ACTIVE','SCHEDULED') or origin='PAID' and verified_at is not null and verified_by is not null);
drop index public.places_one_current_subscription;
create function shiap_private.places_no_overlap() returns trigger language plpgsql security definer set search_path='' as $$begin
 perform 1 from public.places_properties where id=new.property_id for update;
 if new.status in('TRIALING','ACTIVE','SCHEDULED') and exists(select 1 from public.places_subscriptions s where s.property_id=new.property_id and s.id<>new.id and s.status in('TRIALING','ACTIVE','SCHEDULED') and tstzrange(s.starts_at,s.ends_at,'[)')&&tstzrange(new.starts_at,new.ends_at,'[)')) then raise exception 'Periode langganan bertumpuk.' using errcode='PT409';end if;return new;end$$;
revoke all on function shiap_private.places_no_overlap() from public,anon,authenticated;create trigger places_subscription_no_overlap before insert or update on public.places_subscriptions for each row execute function shiap_private.places_no_overlap();
create or replace function shiap_private.places_premium_visible(p_property_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.places_properties p join public.places_subscriptions s on s.property_id=p.id where p.id=p_property_id and p.status='published' and not p.is_demo and p.contact_verified_at is not null and (p.contact_verification_expires_at is null or p.contact_verification_expires_at>now()) and s.status in('TRIALING','ACTIVE','SCHEDULED') and s.starts_at<=now() and s.ends_at>now())$$;
create function public.admin_configure_places_plan(p_id uuid,p_version integer,p_name text,p_price bigint,p_months integer,p_features text[],p_available boolean,p_effective timestamptz,p_promo bigint default null,p_promo_until timestamptz default null) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_name is null or length(btrim(p_name)) not between 2 and 100 or p_price is null or p_price not between 1 and 999999999999 or p_months is null or p_months not in(1,12) or p_features is null or cardinality(p_features)>30 or exists(select 1 from unnest(p_features)f where f is null or length(btrim(f)) not between 1 and 200) or p_available is null or p_effective is null or p_promo is not null and (p_promo<1 or p_promo>p_price or p_promo_until is null) then raise exception 'Paket tidak valid.' using errcode='22023';end if;
 update public.places_premium_plans set name=btrim(p_name),price_idr=p_price,duration_months=p_months,features=p_features,available=p_available,effective_at=p_effective,promo_price_idr=p_promo,promo_until=p_promo_until,version=version+1,updated_by=auth.uid(),updated_at=now() where id=p_id and version=p_version;
 if not found then raise exception 'Paket berubah. Muat ulang.' using errcode='PT409';end if;
 insert into public.places_partner_audit_logs(actor_id,event,new_state) values(auth.uid(),'PREMIUM_PLAN_CHANGED',jsonb_build_object('id',p_id,'version',p_version+1,'price',p_price,'available',p_available));end$$;
create function public.admin_configure_places_billing(p_enabled boolean,p_trial_enabled boolean,p_trial_days integer) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_enabled is null or p_trial_enabled is null or p_trial_days is null or p_trial_days not between 1 and 30 then raise exception 'Konfigurasi tidak valid.' using errcode='22023';end if;
 update public.places_plan_settings set billing_enabled=p_enabled,trial_enabled=p_trial_enabled,trial_days=p_trial_days,updated_at=now(),updated_by=auth.uid() where id;
 insert into public.places_partner_audit_logs(actor_id,event,new_state) values(auth.uid(),'BILLING_CONFIG',jsonb_build_object('enabled',p_enabled,'trial_enabled',p_trial_enabled,'trial_days',p_trial_days));end$$;
create function public.admin_set_places_trial_eligibility(p_property_id uuid,p_eligible boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_eligible is null then raise exception 'Eligibility required.' using errcode='22023';end if;
 insert into public.places_trial_eligibility(property_id,eligible,updated_by) values(p_property_id,p_eligible,auth.uid()) on conflict(property_id) do update set eligible=excluded.eligible,updated_by=auth.uid(),updated_at=now();
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(p_property_id,auth.uid(),'TRIAL_ELIGIBILITY',jsonb_build_object('eligible',p_eligible));end$$;
create function shiap_private.places_lock_billing_owner(p_property_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null then raise exception 'Login required.' using errcode='42501';end if;
 perform 1 from public.places_properties where id=p_property_id and status='published' and not is_demo and contact_verified_at is not null and (contact_verification_expires_at is null or contact_verification_expires_at>now()) for update;
 if not found then raise exception 'Listing terverifikasi diperlukan.' using errcode='22023';end if;
 perform 1 from public.places_property_members where property_id=p_property_id and user_id=auth.uid() and role='OWNER' and status='ACTIVE' for share;
 if not found then raise exception 'Kewenangan owner diperlukan.' using errcode='42501';end if;end$$;
revoke all on function shiap_private.places_lock_billing_owner(uuid) from public,anon,authenticated;
create function public.partner_start_places_trial(p_property_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;days integer;begin
 perform shiap_private.places_lock_billing_owner(p_property_id);
 select id into result from public.places_subscriptions where property_id=p_property_id and origin='TRIAL';if found then return result;end if;
 select trial_days into days from public.places_plan_settings where id and trial_enabled;if not found or not exists(select 1 from public.places_trial_eligibility where property_id=p_property_id and eligible) or not exists(select 1 from public.places_profile_publications where property_id=p_property_id) or exists(select 1 from public.places_subscriptions where property_id=p_property_id and origin='PAID') then raise exception 'Properti belum memenuhi syarat trial.' using errcode='22023';end if;
 insert into public.places_subscriptions(property_id,origin,status,starts_at,ends_at) values(p_property_id,'TRIAL','TRIALING',now(),now()+make_interval(days=>days)) returning id into result;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(p_property_id,auth.uid(),'TRIAL_STARTED',jsonb_build_object('subscription_id',result,'days',days));return result;end$$;
create function public.partner_create_places_invoice(p_property_id uuid,p_plan_id uuid,p_version integer,p_expected_amount bigint,p_request_id uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare plan public.places_premium_plans%rowtype;inv public.places_billing_invoices%rowtype;bank jsonb;price bigint;result uuid;begin
 perform shiap_private.places_lock_billing_owner(p_property_id);
 select * into inv from public.places_billing_invoices where payer_id=auth.uid() and request_id=p_request_id;
 if found then if inv.property_id<>p_property_id or inv.plan_id<>p_plan_id or inv.plan_version<>p_version or inv.amount_idr<>p_expected_amount then raise exception 'Request invoice bertentangan.' using errcode='PT409';end if;return inv.id;end if;
 if p_request_id is null or not exists(select 1 from public.places_plan_settings where id and billing_enabled) then raise exception 'Penagihan Premium belum dibuka.' using errcode='22023';end if;
 select * into plan from public.places_premium_plans where id=p_plan_id and available and effective_at<=now() for share;
 if not found then raise exception 'Paket tidak tersedia.' using errcode='22023';end if;
 price:=case when plan.promo_price_idr is not null and plan.promo_until>now() then plan.promo_price_idr else plan.price_idr end;
 if p_version is distinct from plan.version or p_expected_amount is distinct from price then raise exception 'Harga berubah. Tinjau harga terbaru sebelum membuat invoice.' using errcode='PT409';end if;
 select jsonb_build_object('bank_name',bank_name,'account_name',account_name,'account_number',account_number,'instructions',instructions) into bank from public.payment_settings where id and is_active and length(btrim(bank_name))>0 and length(btrim(account_name))>0 and length(btrim(account_number))>0;
 if bank is null then raise exception 'Rekening pembayaran belum siap.' using errcode='22023';end if;
 update public.places_billing_invoices set status='EXPIRED',updated_at=now() where property_id=p_property_id and status='OPEN' and payment_status in('UNPAID','REQUIRES_ACTION') and deadline_at<=now();
 if exists(select 1 from public.places_billing_invoices where property_id=p_property_id and status='OPEN') then raise exception 'Selesaikan invoice yang masih terbuka.' using errcode='PT409';end if;
 insert into public.places_billing_invoices(property_id,payer_id,request_id,plan_id,plan_version,plan_snapshot,amount_idr,duration_months,bank_snapshot)
 values(p_property_id,auth.uid(),p_request_id,plan.id,plan.version,jsonb_build_object('name',plan.name,'features',plan.features,'duration_months',plan.duration_months,'price_idr',price),price,plan.duration_months,bank) returning id into result;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(p_property_id,auth.uid(),'INVOICE_CREATED',jsonb_build_object('invoice_id',result,'amount_idr',price));return result;end$$;
create function public.partner_cancel_places_invoice(p_invoice_id uuid) returns void language plpgsql security definer set search_path='' as $$declare inv public.places_billing_invoices%rowtype;begin
 select * into inv from public.places_billing_invoices where id=p_invoice_id;if not found then raise exception 'Invoice tidak tersedia.' using errcode='42501';end if;
 perform shiap_private.places_lock_billing_owner(inv.property_id);
 select * into inv from public.places_billing_invoices where id=p_invoice_id and payer_id=auth.uid() for update;if not found then raise exception 'Invoice tidak tersedia.' using errcode='42501';end if;
 if inv.status='CANCELLED' then return;end if;
 if inv.status<>'OPEN' or inv.payment_status not in('UNPAID','REQUIRES_ACTION') then raise exception 'Invoice memerlukan keputusan Admin.' using errcode='PT409';end if;
 update public.places_billing_invoices set status='CANCELLED',updated_at=now() where id=inv.id;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(inv.property_id,auth.uid(),'INVOICE_CANCELLED',jsonb_build_object('invoice_id',inv.id));end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('places-billing-proofs','places-billing-proofs',false,5242880,array['image/webp']) on conflict(id) do nothing;
do $$begin if exists(select 1 from storage.buckets where id='places-billing-proofs' and public) then raise exception 'Proof bucket must be private.';end if;end$$;
create policy places_billing_storage_isolation on storage.objects as restrictive for all to anon,authenticated using(bucket_id<>'places-billing-proofs') with check(bucket_id<>'places-billing-proofs');
create function public.server_submit_places_billing_proof(p_id uuid,p_invoice_id uuid,p_actor uuid,p_path text,p_sha text,p_bytes integer) returns uuid language plpgsql security definer set search_path='' as $$declare inv public.places_billing_invoices%rowtype;old public.places_billing_proofs%rowtype;begin
 select * into inv from public.places_billing_invoices where id=p_invoice_id;if not found then raise exception 'Invoice tidak tersedia.' using errcode='42501';end if;
 perform 1 from public.places_properties where id=inv.property_id for update;
 perform 1 from public.places_property_members where property_id=inv.property_id and user_id=p_actor and role='OWNER' and status='ACTIVE' for share;
 if not found or inv.payer_id<>p_actor then raise exception 'Invoice tidak tersedia.' using errcode='42501';end if;
 select * into inv from public.places_billing_invoices where id=p_invoice_id for update;
 select * into old from public.places_billing_proofs where id=p_id;
 if found then if old.invoice_id<>p_invoice_id or old.submitted_by<>p_actor or old.source_sha256<>p_sha then raise exception 'Request bukti bertentangan.' using errcode='PT409';end if;return old.id;end if;
 if p_id is null or p_path is distinct from inv.id::text||'/'||p_actor::text||'/'||p_id::text||'.webp' or p_sha is null or p_sha !~ '^[a-f0-9]{64}$' or p_bytes is null or p_bytes not between 1 and 5242880 then raise exception 'Bukti tidak valid.' using errcode='22023';end if;
 if inv.status<>'OPEN' or inv.payment_status not in('UNPAID','REQUIRES_ACTION') or inv.deadline_at<=now() then raise exception 'Invoice tidak menerima bukti baru. Hubungi SHIAP jika transfer telah dilakukan.' using errcode='PT409';end if;
 insert into public.places_billing_proofs(id,invoice_id,submitted_by,object_path,source_sha256,byte_size,content_type) values(p_id,inv.id,p_actor,p_path,p_sha,p_bytes,'image/webp');
 update public.places_billing_invoices set payment_status='PENDING_VERIFICATION',updated_at=now() where id=inv.id;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(inv.property_id,p_actor,'BILLING_PROOF_RECEIVED',jsonb_build_object('invoice_id',inv.id,'proof_id',p_id));return p_id;end$$;
revoke all on function public.server_submit_places_billing_proof(uuid,uuid,uuid,text,text,integer) from public,anon,authenticated;grant execute on function public.server_submit_places_billing_proof(uuid,uuid,uuid,text,text,integer) to service_role;
create function public.admin_review_places_invoice(p_invoice_id uuid,p_proof_id uuid,p_approve boolean,p_amount bigint,p_bank_reference text,p_note text,p_confirm_funds boolean,p_request_id uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare inv public.places_billing_invoices%rowtype;proof public.places_billing_proofs%rowtype;receipt public.places_platform_cash_entries%rowtype;result uuid;period_start timestamptz;period_end timestamptz;begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_note is null or length(btrim(p_note)) not between 10 and 2000 or p_approve is null then raise exception 'Catatan review wajib.' using errcode='22023';end if;
 select * into inv from public.places_billing_invoices where id=p_invoice_id;if not found then raise exception 'Invoice tidak tersedia.' using errcode='P0002';end if;
 perform 1 from public.places_properties where id=inv.property_id for update;
 select * into inv from public.places_billing_invoices where id=p_invoice_id for update;
 if p_approve then select * into receipt from public.places_platform_cash_entries where invoice_id=inv.id and entry_type='RECEIPT';
 if found then if receipt.request_id is distinct from p_request_id or receipt.amount_idr is distinct from p_amount or receipt.bank_reference is distinct from btrim(p_bank_reference) then raise exception 'Invoice sudah diverifikasi dengan request berbeda.' using errcode='PT409';end if;return inv.subscription_id;end if;end if;
 select * into proof from public.places_billing_proofs where id=p_proof_id and invoice_id=inv.id for update;
 if not found or inv.status<>'OPEN' or inv.payment_status<>'PENDING_VERIFICATION' or proof.status<>'PENDING' then raise exception 'Bukti tidak menunggu verifikasi.' using errcode='PT409';end if;
 -- A timely proof remains reviewable after invoice deadline. This domain holds no booking inventory.
 if not p_approve then
 update public.places_billing_proofs set status='REJECTED',review_note=btrim(p_note),reviewed_at=now(),reviewed_by=auth.uid() where id=proof.id;
 update public.places_billing_invoices set payment_status='REQUIRES_ACTION',updated_at=now() where id=inv.id;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(inv.property_id,auth.uid(),'BILLING_PROOF_REJECTED',jsonb_build_object('invoice_id',inv.id,'proof_id',proof.id));return null;end if;
 if p_confirm_funds is distinct from true or p_amount is distinct from inv.amount_idr or p_request_id is null or p_bank_reference is null or length(btrim(p_bank_reference)) not between 6 and 200 then raise exception 'Periksa dana bank dan jumlah penuh 100%%.' using errcode='22023';end if;
 if exists(select 1 from public.places_subscriptions where property_id=inv.property_id and status='SUSPENDED') then raise exception 'Selesaikan penangguhan dengan Admin sebelum aktivasi.' using errcode='PT409';end if;
 select greatest(now(),coalesce(max(ends_at),now())) into period_start from public.places_subscriptions where property_id=inv.property_id and status in('TRIALING','ACTIVE','SCHEDULED') and ends_at>now();
 period_end:=period_start+make_interval(months=>inv.duration_months);
 insert into public.places_subscriptions(property_id,origin,status,starts_at,ends_at,verified_at,verified_by) values(inv.property_id,'PAID',case when period_start>now() then 'SCHEDULED' else 'ACTIVE' end,period_start,period_end,now(),auth.uid()) returning id into result;
 insert into public.places_platform_cash_entries(invoice_id,request_id,entry_type,amount_idr,bank_reference,note,verified_by) values(inv.id,p_request_id,'RECEIPT',p_amount,btrim(p_bank_reference),btrim(p_note),auth.uid());
 update public.places_billing_proofs set status='APPROVED',reviewed_at=now(),reviewed_by=auth.uid(),review_note='Dana pembayaran penuh telah diverifikasi Admin.' where id=proof.id;
 update public.places_billing_invoices set status='SETTLED',payment_status='PAID',subscription_id=result,settled_at=now(),updated_at=now() where id=inv.id;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(inv.property_id,auth.uid(),'PREMIUM_PAYMENT_VERIFIED',jsonb_build_object('invoice_id',inv.id,'subscription_id',result,'amount_idr',p_amount,'starts_at',period_start,'ends_at',period_end));return result;end$$;
create function public.admin_refund_places_invoice(p_invoice_id uuid,p_amount bigint,p_bank_reference text,p_note text,p_confirm_funds boolean,p_request_id uuid,p_suspend boolean) returns void language plpgsql security definer set search_path='' as $$declare inv public.places_billing_invoices%rowtype;old public.places_platform_cash_entries%rowtype;refunded bigint;begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_confirm_funds is distinct from true or p_amount is null or p_amount<1 or p_request_id is null or p_suspend is null or p_note is null or length(btrim(p_note)) not between 10 and 2000 or p_bank_reference is null or length(btrim(p_bank_reference)) not between 6 and 200 then raise exception 'Konfirmasi transfer refund nyata dan alasan diperlukan.' using errcode='22023';end if;
 select * into inv from public.places_billing_invoices where id=p_invoice_id;if not found then raise exception 'Invoice tidak tersedia.' using errcode='P0002';end if;
 perform 1 from public.places_properties where id=inv.property_id for update;
 select * into inv from public.places_billing_invoices where id=p_invoice_id for update;
 select * into old from public.places_platform_cash_entries where request_id=p_request_id;
 if found then if old.invoice_id<>inv.id or old.entry_type<>'REFUND' or old.amount_idr<>p_amount or old.bank_reference<>btrim(p_bank_reference) then raise exception 'Request refund bertentangan.' using errcode='PT409';end if;return;end if;
 if inv.status<>'SETTLED' then raise exception 'Invoice belum dibayar.' using errcode='PT409';end if;
 select coalesce(sum(amount_idr),0) into refunded from public.places_platform_cash_entries where invoice_id=inv.id and entry_type='REFUND';
 if p_amount>inv.amount_idr-refunded then raise exception 'Refund melebihi dana diterima.' using errcode='22023';end if;
 insert into public.places_platform_cash_entries(invoice_id,request_id,entry_type,amount_idr,bank_reference,note,verified_by) values(inv.id,p_request_id,'REFUND',p_amount,btrim(p_bank_reference),btrim(p_note),auth.uid());
 update public.places_billing_invoices set payment_status=case when refunded+p_amount=amount_idr then 'REFUNDED' else 'PARTIALLY_REFUNDED' end,updated_at=now() where id=inv.id;
 if p_suspend or refunded+p_amount=inv.amount_idr then update public.places_subscriptions set status='SUSPENDED',updated_at=now() where id=inv.subscription_id;end if;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(inv.property_id,auth.uid(),'PREMIUM_REFUND_RECORDED',jsonb_build_object('invoice_id',inv.id,'amount_idr',p_amount,'suspended',p_suspend or refunded+p_amount=inv.amount_idr));end$$;
revoke all on function public.admin_configure_places_plan(uuid,integer,text,bigint,integer,text[],boolean,timestamptz,bigint,timestamptz),public.admin_configure_places_billing(boolean,boolean,integer),public.admin_set_places_trial_eligibility(uuid,boolean),public.partner_start_places_trial(uuid),public.partner_create_places_invoice(uuid,uuid,integer,bigint,uuid),public.partner_cancel_places_invoice(uuid),public.admin_review_places_invoice(uuid,uuid,boolean,bigint,text,text,boolean,uuid),public.admin_refund_places_invoice(uuid,bigint,text,text,boolean,uuid,boolean) from public,anon;
grant execute on function public.admin_configure_places_plan(uuid,integer,text,bigint,integer,text[],boolean,timestamptz,bigint,timestamptz),public.admin_configure_places_billing(boolean,boolean,integer),public.admin_set_places_trial_eligibility(uuid,boolean),public.partner_start_places_trial(uuid),public.partner_create_places_invoice(uuid,uuid,integer,bigint,uuid),public.partner_cancel_places_invoice(uuid),public.admin_review_places_invoice(uuid,uuid,boolean,bigint,text,text,boolean,uuid),public.admin_refund_places_invoice(uuid,bigint,text,text,boolean,uuid,boolean) to authenticated;
create or replace view public.places_public_plan_v with(security_barrier=true) as select id,premium_monthly_price_idr,price_status,max_units,premium_enabled,premium_yearly_price_idr,trial_enabled,trial_days,billing_enabled from public.places_plan_settings where id=true;
create function public.partner_cancel_places_subscription(p_id uuid) returns void language plpgsql security definer set search_path='' as $$declare s public.places_subscriptions%rowtype;begin
 select * into s from public.places_subscriptions where id=p_id;if not found then raise exception 'Langganan tidak tersedia.' using errcode='42501';end if;
 perform 1 from public.places_properties where id=s.property_id for update;
 perform 1 from public.places_property_members where property_id=s.property_id and user_id=auth.uid() and status='ACTIVE' and role='OWNER' for share;if not found then raise exception 'Owner diperlukan.' using errcode='42501';end if;
 select * into s from public.places_subscriptions where id=p_id for update;
 if s.status='CANCELLED' then return;end if;if s.status not in('TRIALING','ACTIVE','SCHEDULED') then raise exception 'Periode sudah tidak aktif.' using errcode='PT409';end if;
 update public.places_subscriptions set status='CANCELLED',updated_at=now() where id=s.id;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(s.property_id,auth.uid(),'SUBSCRIPTION_CANCELLED',jsonb_build_object('id',s.id,'refund_automatic',false));end$$;
revoke all on function public.partner_cancel_places_subscription(uuid) from public,anon;grant execute on function public.partner_cancel_places_subscription(uuid) to authenticated;

commit;
